cd /tmp && rm -rf stubcheck && mkdir -p stubcheck/caruca/ir stubcheck/pash_annotations/annotation_generation/annotation_generators && cd stubcheck
touch caruca/__init__.py caruca/ir/__init__.py pash_annotations/__init__.py pash_annotations/annotation_generation/__init__.py pash_annotations/annotation_generation/annotation_generators/__init__.py
cat > caruca/ir/syntax.py <<'EOF'
import enum
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
SyntaxSpecification = list
class Flag:
    def __init__(self, flag, alias=()): self.flag=flag; self.alias=list(alias)
class Path:
    def __init__(self, flag=None, alias=(), flag_followed_by_equals=False, arity=Arity.OPTIONAL, dash_as_stdin=False):
        self.flag=flag; self.arity=arity; self.dash_as_stdin=dash_as_stdin
EOF
cat > pash_annotations/annotation_generation/annotation_generators/InputOutputInfoGenerator_Interface.py <<'EOF'
class InputOutputInfoGeneratorInterface:
    def __init__(self): self.calls=[]
    def set_all_operands_as_config_arg_type_string(self): self.calls.append("operands=config-string")
    def set_implicit_use_of_stdout(self): self.calls.append("stdout")
EOF
cat > pash_annotations/annotation_generation/annotation_generators/ParallelizabilityInfoGenerator_Interface.py <<'EOF'
class ParallelizabilityInfoGeneratorInterface:
    def __init__(self): self.parallelizers=[]
EOF
cp -r /home/tirandagan.guest/naive-arm/output/pash ./pash_out && cp /home/tirandagan.guest/naive-arm/output/dirname.py .
python3 -c "
import dirname
s=dirname.dirname_syntax_spec; print('syntaxes',len(s),'flags',[f.flag for f in s[0][0]],'operand arity',s[0][1][0].arity, 'dash_as_stdin', s[0][1][0].dash_as_stdin)
import sys; sys.path.insert(0,'pash_out')
from InputOutputInfoGeneratorDirname import InputOutputInfoGeneratorDirname as IO
from ParallelizabilityInfoGeneratorDirname import ParallelizabilityInfoGeneratorDirname as P
g=IO(); g.generate_info(); print('io calls',g.calls)
p=P(); p.generate_info(); print('parallelizers',p.parallelizers)
"

